def connected_component_count(grid):
    """Count connected components in grid"""
    if not grid or not grid[0]:
        return []

    h, w = len(grid), len(grid[0])
    visited = [[False]*w for _ in range(h)]

    def bfs(r, c, target):
        count = 1
        visited[r][c] = True
        q = [(r,c)]
        while q:
            cr, cc = q.pop()
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = cr+dr, cc+dc
                if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc] and grid[nr][nc] == target:
                    visited[nr][nc] = True
                    q.append((nr,nc))
                    count += 1
        return count

    components = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and not visited[r][c]:
                size = bfs(r, c, grid[r][c])
                components.add((r, c, size))
    return list(components)

