def check_isolated(row_idx, grid):
    """Check if all non-bg cells in this row are isolated (no orthogonal neighbors with same color)"""
    h, w = len(grid), len(grid[0])
    bg = max(set(sum(grid[i] for i in range(h)), []), key=lambda x: sum(1 for r in grid for c in r if x==c))
    isolated_row = True
    for c in range(w):
        if grid[row_idx][c] != bg:
            # Check all 4 neighbors
            if any(grid[r][c] == grid[row_idx][c] for r in [row_idx-1, row_idx+1] if 0 <= r < h):
                isolated_row = False
                break
            if any(grid[row_idx][cc] == grid[row_idx][c] for cc in [c-1, c+1] if 0 <= cc < w):
                isolated_row = False
                break
    return isolated_row

