def solve(grid):
    """Remove the topmost row containing non-bg color, fill that row's position with bg"""
    if not grid or not grid[0]:
        return []

    h, w = len(grid), len(grid[0])

    # Count colors to find background
    colors = {}
    for r in range(h):
        for c in range(w):
            colors[grid[r][c]] = colors.get(grid[r][c], 0) + 1
    bg = max(colors, key=colors.get)

    # Find first row with non-bg color
    first_non_bg_row = None
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                first_non_bg_row = r
                break
        if first_non_bg_row is not None:
            break

    if first_non_bg_row is None:
        # No non-bg, return copy of input
        return [[row[:] for row in grid]]

    # Build result: bg-filled row at top, then skip first_non_bg_row
    result = [[bg]*w]
    for r in range(h):
        if r != first_non_bg_row:
            result.append([grid[r][c] for c in range(w)])

    return result

