    first_non_bg_row = None
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                first_non_bg_row = r
                break
        if first_non_bg_row is not None:
            break

    if first_non_bg_row is None:
        # No non-bg, return copy of input
        return [[row[:] for row in grid]]

    # Build result: 
    # - Position 0: filled with bg
    # - Positions 1 to (h - first_non_bg_row): copies from input rows 0 to (h - 1 - first_non_bg_row)
    # - Remaining positions: keep original values from after the removed row

    result = []
