def solve_v3(grid):
    """Remove the topmost row containing non-bg color, fill that row's position with bg"""
    if not grid or not grid[0]:
        return []

    h, w = len(grid), len(grid[0])

    # Count colors to find background
    colors = {}
    for r in range(h):
        for c in range(w):
            colors[grid[r][c]] = colors.get(grid[r][c], 0) + 1
    bg = max(colors, key=colors.get)

    # Find first row with non-bg color
    first_non_bg_row = None
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                first_non_bg_row = r
                break
        if first_non_bg_row is not None:
            break

    if first_non_bg_row is None:
        # No non-bg, return copy of input
        return [[row[:] for row in grid]]

    # Build result: same number of rows as input
    result = [[None]*w for _ in range(h)]

    # Fill removed row's position (first_non_bg_row) with bg
    for c in range(w):
        result[first_non_bg_row][c] = bg

    # Copy everything ABOVE the removed row - stays in place
    for r in range(first_non_bg_row):
        for c in range(w):
            result[r][c] = grid[r][c]

    # Copy everything BELOW the removed row - shifts UP by 1
    # Row (first_non_bg_row + 1) becomes (first_non_bg_row + 1)
    # Wait no... row (first_non_bg_row + k) becomes (first_non_bg_row + k) in output?
    # Actually we're replacing one row, so rows below shift up
    # Output row (first_non_bg_row + 1) = Input row (first_non_bg_row + 2)

    for r in range(first_non_bg_row + 1, h):
        src_r = r + 1  # Source is one row below
        if src_r < h:
            for c in range(w):
                result[r][c] = grid[src_r][c]

    return result

